code:
// arranque-intro · REQ-INTRO1 / REQ-INTRO2 · la intro de CUALQUIER mapa abierto con ?intro=1
//
// Lo que ve quien abre la URL: la cámara sobrevolando el mapa YA RENDERIZADO, en tiempo real, con un
// menú encima que ofrece JUGAR y CONSTRUIR. La animación vive AQUÍ y no en app.js: app.js solo sabe
// cuándo llamar a este snippet (mcIntroArranque).
//
// app.js busca primero `arranque-<mapa>` y, si no existe, este. Está escrito contra `mc.dim`, así que
// se orienta solo en un mapa que no ha visto nunca: para darle intro a un mundo nuevo no hay que tocar
// nada. Si un mapa concreto quiere OTRA intro, se copia esto a `arranque-<ese mapa>` y esa gana.
//
// Reglas que cuestan caro romper aquí:
//   - El estado vive en `mc._intro`, NO en un closure: reejecutar el snippet a mitad de la órbita tiene
//     que poder parar la anterior. Sin esto, dos bucles pelean por la misma cámara y se ve un temblor.
//   - NINGUNO de los dos botones recarga la página: el mapa ya está cargado y esa era la gracia del
//     encargo. JUGAR aterriza en el sitio; CONSTRUIR cierra el Mundo y descubre el editor, que está
//     debajo en la misma página (y la marca «VOXELFORGE» del editor vuelve aquí).
//   - La captura del ratón va DENTRO del manejador del clic (es gesto de usuario). Pedirla tras un
//     await o un rAF la rechaza el navegador y el jugador aterriza sin poder mirar.

const VERSION = 5;

// 1 · desmontar la intro anterior antes de montar la nueva
if (mc._intro && mc._intro.parar) mc._intro.parar();

const CFG = {
  alturaOjo: 16,      // celdas por encima de la copa del terreno
  radio: Math.min(mc.dim.x, mc.dim.z) * 0.30,
  vueltaSeg: 120,     // lo que tarda una vuelta entera: lento a propósito, es una postal
  pitch: -16 * Math.PI / 180,
  suavizado: 0.03     // la vertical persigue al terreno; sin esto, cada pico es un salto
};

// La cima sólida de una columna (−1 si no hay nada): sirve para volar por encima y para aterrizar.
function cima(x, z) {
  x = Math.floor(x); z = Math.floor(z);
  if (!mcInside(x, 0, z)) return -1;
  for (let y = mc.dim.y - 1; y >= 0; y--) if (mc.grid[mcIdx(x, y, z)]) return y;
  return -1;
}

const cx = mc.dim.x / 2, cz = mc.dim.z / 2;
const MOVER = { KeyW:1, KeyA:1, KeyS:1, KeyD:1, Space:1, ArrowUp:1, ArrowDown:1, ArrowLeft:1, ArrowRight:1 };

const intro = mc._intro = {
  raf: 0, t0: performance.now(), y: null, viva: true,
  parar() {
    if (!this.viva) return;
    this.viva = false;
    if (this.raf) cancelAnimationFrame(this.raf);
    this.raf = 0;
    window.removeEventListener('keydown', alTeclear, true);
    document.body.classList.remove('mc-intro');   // devuelve hotbar, mira y botones de esquina
    if (mc._intro === this) mc._intro = null;
  }
};

// Quien ya sabe lo que quiere no espera a la animación: tocar una tecla de moverse es decir JUGAR.
function alTeclear(e) {
  if (!intro.viva || e.ctrlKey || e.altKey || e.metaKey) return;
  if (MOVER[e.code]) jugar();
}
window.addEventListener('keydown', alTeclear, true);

game.volar(true);
game.fantasma(true);   // la órbita pasa por donde pasa: un pino a media altura no puede pararla
// Durante el sobrevuelo esto no es una partida todavía, es una postal: fuera hotbar, mira y los botones
// de «Código» y «Cerrar» de la esquina (CSS `body.mc-intro`, en style.css). Lo quita `parar()`, así que
// JUGAR —y cualquier tecla de moverse— lo devuelve todo. Va por clase y no por `hidden` porque
// `mcUpdateHotbar` re-enseña la hotbar sola en cuanto el jugador se mueve.
document.body.classList.add('mc-intro');

function paso(now) {
  if (!intro.viva) return;
  const a = (now - intro.t0) / 1000 * 2 * Math.PI / CFG.vueltaSeg;
  const x = cx + Math.cos(a) * CFG.radio, z = cz + Math.sin(a) * CFG.radio;
  const objetivo = cima(x, z) + 1 + CFG.alturaOjo;
  intro.y = intro.y == null ? objetivo : intro.y + (objetivo - intro.y) * CFG.suavizado;
  mc.pos[0] = x; mc.pos[1] = intro.y; mc.pos[2] = z;
  mc.vel = [0, 0, 0];
  // Mirando al centro del mapa. La dirección de vista es [−sin(yaw)·cp, sin(pitch), −cos(yaw)·cp],
  // así que apuntar a (dx,dz) es yaw = atan2(−dx, −dz). No se inventa otra convención.
  mc.yaw = Math.atan2(-(cx - x), -(cz - z));
  mc.pitch = CFG.pitch;
  intro.raf = requestAnimationFrame(paso);
}
intro.raf = requestAnimationFrame(paso);

// 2 · el menú. Con {html:…} funciona hoy; el día que el dueño dibuje /map/menu1 es cambiar esta
// línea por {mapa:'menu1'} y NO se toca ni una de las acciones: un botón se declara por su texto.
game.osd.define('intro', { html:
  '<div class="mc-osd-panel">' +
    '<div class="mc-osd-title">VoxelForge v1.0</div>' +
    '<button class="mc-osd-btn">JUGAR</button>' +
    '<button class="mc-osd-btn">CONSTRUIR</button>' +
  '</div>' });

// Las dos acciones NO reciben nada: son funciones de cero parámetros que usan `intro` y `cima`, que
// viven aquí dentro. Lo que se DECLARA abajo, en el 3.er argumento de `alPulsar`, es justo eso: qué
// usan de este snippet. No cambia cómo corren; hace que `game.osd.dump()` imprima delante la línea
// `const {intro, cima} = game.osd.entorno('JUGAR');` y el ejemplo se pueda copiar entero y correr.
function jugar() {
  intro.parar();
  game.fantasma(false);
  game.volar(false);
  // Aterrizar donde estaba mirando la cámara: la superficie de la columna de debajo. Se coloca a mano
  // en vez de con game.tp para no soltar su toast («Saltaste a …») en la cara del que acaba de entrar;
  // mcUnstick, que es lo útil de tp, sí se llama.
  const x = Math.floor(mc.pos[0]), z = Math.floor(mc.pos[2]);
  mc.pos = [x + 0.5, cima(x, z) + 1, z + 0.5];
  mc.vel = [0, 0, 0]; mc.onGround = false;
  mcUnstick();
  game.osd.cerrar();
  mcLockPointer();     // ← gesto de usuario: aquí sí, en un await ya no
}

// CONSTRUIR · el editor 2D/3D está DEBAJO, en esta misma página: el Mundo es el overlay #mc-modal. Así
// que se cierra el Mundo y ya está — nada de location.href='/', que recargaba la página entera y volvía
// a bajar mundo, atlas y galerías (REQ-INTRO2). Al cerrar, la marca «VOXELFORGE» del editor se vuelve
// pulsable y trae de vuelta aquí, también sin recargar.
function construir() {
  intro.parar();
  game.fantasma(false);
  game.volar(false);
  game.osd.cerrar();
  closeWorld();
}

game.osd.alPulsar('JUGAR', jugar, { intro, cima });
game.osd.alPulsar('CONSTRUIR', construir, { intro });
game.osd.abrir('intro');

console.log('arranque-intro v' + VERSION + ': intro en marcha en «' + mcMapName() + '» (cualquier tecla de moverse = JUGAR)');
